svg.script:
(function () {
  var dark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

  var colors = dark ? {
    neutral:  { fill: '#2a2a28', stroke: '#c3c2b7', width: 1.5 },
    idle:     { fill: '#16263a', stroke: '#7fa6d6', width: 2.5 },
    recording:{ fill: '#3a2317', stroke: '#ef7a63', width: 2.5 },
    thinking: { fill: '#241c35', stroke: '#9b7ee0', width: 2.5 },
    speaking: { fill: '#16321f', stroke: '#4cc274', width: 2.5 },
    qWaiting: { fill: '#142a42', stroke: '#3987e5', width: 2 },
    bgWaiting:{ fill: '#3a2d10', stroke: '#d9a93a', width: 2 },
    delivered:{ fill: '#142a42', stroke: '#3987e5', width: 2.5 }
  } : {
    neutral:  { fill: '#f2f1ee', stroke: '#52514e', width: 1.5 },
    idle:     { fill: '#eef3fb', stroke: '#5b7a9e', width: 2.5 },
    recording:{ fill: '#fdece3', stroke: '#d6563f', width: 2.5 },
    thinking: { fill: '#f1ecfb', stroke: '#6b46c1', width: 2.5 },
    speaking: { fill: '#e5f5ea', stroke: '#2f9e52', width: 2.5 },
    qWaiting: { fill: '#e7f0fb', stroke: '#2a78d6', width: 2 },
    bgWaiting:{ fill: '#fdf3d9', stroke: '#b8860b', width: 2 },
    delivered:{ fill: '#e7f0fb', stroke: '#2a78d6', width: 2.5 }
  };

  function paint(el, c) {
    el.style.fill = c.fill;
    el.style.stroke = c.stroke;
    el.style.strokeWidth = c.width;
  }

  var steps = [
    { state: 'idle', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Runde 1 -- Leerlauf', cap2: 'Kein Turn aktiv, beide Queues leer' },
    { state: 'idle', inputQ: 'empty', inputSub: '', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Hintergrund-Ergebnis trifft ein', cap2: 'z.B. ein Build-Agent meldet sich unaufgefordert' },
    { state: 'speaking', inputQ: 'empty', inputSub: '', bg: 'delivered', bgSub: 'Build-Agent: fertig', connector: true,
      cap1: 'Sofort zugestellt', cap2: 'App stößt selbst einen Mini-Turn an -- Push, nicht Pull' },
    { state: 'idle', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Zurück im Leerlauf', cap2: 'Bereit für den nächsten Eintrag' },
    { state: 'recording', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Runde 2 -- Nutzer nimmt auf', cap2: 'z.B. "mach die lange Aufgabe"' },
    { state: 'thinking', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Aufnahme endet, Turn beginnt', cap2: 'Transkript landet in der Eingabe-Queue und wird sofort verarbeitet' },
    { state: 'thinking', inputQ: 'waiting', inputSub: '"wie weit bist du?"', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Nutzer schickt während der Verarbeitung eine Folgefrage', cap2: 'Steering: reiht sich hinten ein, laufender Turn läuft unbeeindruckt weiter' },
    { state: 'thinking', inputQ: 'waiting', inputSub: '"wie weit bist du?"', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Hintergrund-Ergebnis trifft ein', cap2: 'wird nicht sofort zugestellt -- reiht sich hinten ein' },
    { state: 'speaking', inputQ: 'waiting', inputSub: '"wie weit bist du?"', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Erste Antwort wird gesprochen', cap2: 'Hintergrund-Meldung bleibt grau/wartend' },
    { state: 'thinking', inputQ: 'draining', inputSub: '"wie weit bist du?"', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Wartende Folgefrage hat Vorrang', cap2: 'Responder-Loop nimmt sie zuerst aus der Eingabe-Queue' },
    { state: 'speaking', inputQ: 'empty', inputSub: '', bg: 'delivered', bgSub: 'Build-Agent: fertig', connector: true,
      cap1: 'Jetzt erst: Hintergrund-Queue wird geflusht', cap2: 'Erst wenn die Eingabe-Queue leer ist' },
    { state: 'idle', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Zurück im Leerlauf', cap2: '' },
    { state: 'recording', inputQ: 'empty', inputSub: '', bg: 'empty', bgSub: '', connector: false,
      cap1: 'Runde 3 -- Aufnahme läuft', cap2: 'Mikrofon aktiv, Nutzer spricht gerade' },
    { state: 'recording', inputQ: 'empty', inputSub: '', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Hintergrund-Ergebnis trifft ein', cap2: 'keine Audioausgabe, solange aufgenommen wird' },
    { state: 'thinking', inputQ: 'draining', inputSub: '(Transkript aus der Aufnahme)', bg: 'waiting', bgSub: 'Build-Agent: fertig', connector: false,
      cap1: 'Aufnahme endet, neuer Turn startet', cap2: 'Hintergrund-Meldung wartet weiterhin' },
    { state: 'speaking', inputQ: 'empty', inputSub: '', bg: 'delivered', bgSub: 'Build-Agent: fertig', connector: true,
      cap1: 'Transkript wird zuerst beantwortet, dann zugestellt', cap2: 'Nie über eine laufende Aufnahme drüberreden' }
  ];

  var boxes = {
    idle: document.getElementById('idleBox'),
    recording: document.getElementById('recordingBox'),
    thinking: document.getElementById('thinkingBox'),
    speaking: document.getElementById('speakingBox')
  };
  var inputQueueBox = document.getElementById('inputQueueBox');
  var inputQueueMain = document.getElementById('inputQueueMain');
  var inputQueueSub = document.getElementById('inputQueueSub');
  var bgQueueBox = document.getElementById('bgQueueBox');
  var bgQueueMain = document.getElementById('bgQueueMain');
  var bgQueueSub = document.getElementById('bgQueueSub');
  var connectorGroup = document.getElementById('connectorGroup');
  var capLine1 = document.getElementById('capLine1');
  var capLine2 = document.getElementById('capLine2');
  var stepIndicator = document.getElementById('stepIndicator');

  var step = 1;

  function render() {
    var s = steps[step - 1];

    Object.keys(boxes).forEach(function (key) {
      paint(boxes[key], key === s.state ? colors[key] : colors.neutral);
    });

    if (s.inputQ === 'empty') {
      paint(inputQueueBox, colors.neutral);
      inputQueueMain.textContent = 'leer';
      inputQueueSub.textContent = '';
    } else if (s.inputQ === 'waiting') {
      paint(inputQueueBox, colors.qWaiting);
      inputQueueMain.textContent = '1 wartend';
      inputQueueSub.textContent = s.inputSub;
    } else if (s.inputQ === 'draining') {
      paint(inputQueueBox, colors.qWaiting);
      inputQueueMain.textContent = 'wird jetzt verarbeitet';
      inputQueueSub.textContent = s.inputSub;
    }

    if (s.bg === 'empty') {
      paint(bgQueueBox, colors.neutral);
      bgQueueMain.textContent = 'leer';
      bgQueueSub.textContent = '';
    } else if (s.bg === 'waiting') {
      paint(bgQueueBox, colors.bgWaiting);
      bgQueueMain.textContent = '1 Ergebnis wartet';
      bgQueueSub.textContent = s.bgSub;
    } else if (s.bg === 'delivered') {
      paint(bgQueueBox, colors.delivered);
      bgQueueMain.textContent = 'zugestellt';
      bgQueueSub.textContent = s.bgSub;
    }

    connectorGroup.style.opacity = s.connector ? '1' : '0';
    capLine1.textContent = s.cap1;
    capLine2.textContent = s.cap2;
    stepIndicator.textContent = step + ' / ' + steps.length;
  }

  function next() { step = (step >= steps.length) ? 1 : step + 1; render(); }
  function prev() { step = (step <= 1) ? steps.length : step - 1; render(); }

  document.getElementById('nextBtn').addEventListener('click', next);
  document.getElementById('prevBtn').addEventListener('click', prev);
  document.getElementById('bgClick').addEventListener('click', next);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight' || e.key === ' ') { next(); e.preventDefault(); }
    if (e.key === 'ArrowLeft') { prev(); e.preventDefault(); }
  });

  render();
})();
